const { execSync } = require('child_process');
const { id, format, max_chars = 50000 } = $json.body;
if (!id || !format) return [{ json: { error: 'Missing id or format' } }];
if (format.toLowerCase() === 'pdf') return [{ json: { error: 'PDF not supported for text extraction, use epub' } }];

try {
  const url = `http://localhost:8083/download/${id}/${format.toLowerCase()}`;
  const tmpFile = `/tmp/book_${id}.epub`;
  execSync(`curl -s -L -o ${tmpFile} ${url}`);
  const unzipOutput = execSync(`unzip -p ${tmpFile} '*.xhtml' '*.html' 2>/dev/null || echo ''`, {encoding: 'utf-8'});
  let text = unzipOutput.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
  const total_chars = text.length;
  let content_truncated = false;
  if (text.length > max_chars) {
    text = text.substring(0, max_chars);
    content_truncated = true;
  }
  return [{ json: { status: 'ok', source: 'calibre', title: `Book ${id}`, content: text, content_truncated, total_chars } }];
} catch (err) {
  return [{ json: { error: err.message } }];
}

const { query } = $json.body;
if (!query) return [{ json: { error: 'Missing query' } }];
// Mock implementation for search_all to illustrate the node
// Real implementation would use fetch() or axios() to hit Notion API for each DB
return [{ json: { status: 'ok', results: [{type: 'book', title: 'Example Book matching ' + query}] } }];

